INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_description','تعرف على مقارنات اللوله النخدار بقطر 160 ملم. دليل شامل للمزارعين العراقيين لاختيار نظام الري القطري ونظام النوار المناسب لحقلهم.' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_description');
