INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_description','In-depth technical comparison of 160mm ribbed pipes vs. competing brands for drip and Tefrip irrigation. Learn selection criteria for optimal performance and longevity.' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_description');
