INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_description','Муқоисаи муфассали фанавии лабоби нахии 160 мм бо брендҳои дигар барои системҳои абории сипарона ва навар тиби. Равонамои комил барои деҳқонони тоҷик то интихоби дурустро кардан. Афориши коркарди маълумот (AFP).' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_description');
